const uif_glyph_t *uif_lookup(const uif_font_t *font, uint32_t cp)
{
    int lo = 0, hi = font->count - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        uint32_t m = font->glyphs[mid]->cp;
        if (m == cp) return font->glyphs[mid];
        if (m < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
